139	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
140	     * namesake count is treated as not being zero, so it contributes nothing.
141	     */
142	    default Integer formatMembershipPoints(Owner owner) {
143	        if (owner == null) {
144	            return null;
145	        }
146	        int points = 0;
147	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
148	        if (hasEmail) {
149	            points += 2;
150	        }
151	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
152	        if (uniqueName) {
153	            points += 1;
154	        }
155	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
156	        if (householdSize >= 3) {
157	            points += 2;
158	        }
159	        LocalDate registrationDate = owner.getRegistrationDate();
160	        if (registrationDate != null
161	            && fiscalYearEndYear(LocalDate.now()) - fiscalYearEndYear(registrationDate) > 1) {
162	            points += 3;
