190	    /**
191	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
192	     * contained in the owner's {@code customerCode}. Non-digit characters (the region segment
193	     * and any hex letters of the hash) are ignored. Returns {@code null} when the owner or its
194	     * customer code is absent, since the digit cannot be derived without the code.
195	     */
196	    default Integer formatCheckDigit(Owner owner) {
197	        if (owner == null || owner.getCustomerCode() == null) {
198	            return null;
199	        }
200	        String code = owner.getCustomerCode();
201	        int sum = 0;
202	        boolean dbl = true;
203	        for (int i = code.length() - 1; i >= 0; i--) {
204	            char c = code.charAt(i);
205	            if (c < '0' || c > '9') {
206	                continue;
207	            }
208	            int d = c - '0';
209	            if (dbl) {
210	                d *= 2;
211	                if (d > 9) {
212	                    d -= 9;
213	                }
214	            }
215	            sum += d;
216	            dbl = !dbl;
217	        }
218	        return (10 - (sum % 10)) % 10;
219	    }
