229	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
230	            return null;
231	        }
232	        return String.format("%s-M%02d", owner.getCustomerCode(),
233	            fiscalYearEndYear(owner.getRegistrationDate()) % 100);
234	    }
235	
236	    /**
237	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the last two digits
238	     * of the fiscal year its (business-day-adjusted) {@code registrationDate} falls in (e.g.
239	     * {@code "FY26"}). The fiscal year starts on 1 July and is named by the calendar year in
240	     * which it ends, so a registration date of {@code 2026-07-01} is {@code "FY27"} while
241	     * {@code 2026-06-30} is {@code "FY26"}. Returns {@code null} when the owner or its
242	     * registration date is absent.
243	     */
244	    default String formatFiscalYear(Owner owner) {
245	        if (owner == null || owner.getRegistrationDate() == null) {
246	            return null;
247	        }
248	        return String.format("FY%02d", fiscalYearEndYear(owner.getRegistrationDate()) % 100);
249	    }
