251	    /**
252	     * The calendar year in which {@code date}'s fiscal year ends, used as the fiscal year's name.
253	     * The fiscal year starts on 1 July, so a date in July through December belongs to the fiscal
254	     * year ending the following calendar year, while January through June belongs to the one
255	     * ending in the current calendar year.
256	     */
257	    default int fiscalYearEndYear(LocalDate date) {
258	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
259	    }
260	
261	    /**
262	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
263	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
264	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
265	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
266	     */
267	    default String formatTelephoneDisplay(Owner owner) {
268	        if (owner == null) {
269	            return null;
270	        }
271	        return E164Telephone.toDisplay(owner.getTelephone());
272	    }
273	
274	    /**
275	     * Compose an owner's salutation as its {@code title} followed by a single space and the
276	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
277	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
278	     */
279	    default String formatSalutation(Owner owner) {
280	        if (owner == null) {
281	            return null;
282	        }
283	        String title = owner.getTitle();
284	        if (title == null || title.trim().isEmpty()) {
285	            return owner.getLastName();
286	        }
287	        return title + " " + owner.getLastName();
288	    }
289	
290	    /**
291	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
292	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
293	     * be formed without an id.
294	     */
295	    default String formatSelfLink(Owner owner) {
296	        if (owner == null || owner.getId() == null) {
297	            return null;
298	        }
299	        return "/api/owners/" + owner.getId();
300	    }
301	
302	    /**
303	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
304	     */
305	    default String formatDisplayName(Owner owner) {
306	        if (owner == null) {
307	            return null;
308	        }
309	        return owner.getLastName() + ", " + owner.getFirstName();
310	    }
311	
312	    /**
313	     * Format an owner's initials as the upper-cased first letters of the first and last
314	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
315	     */
316	    default String formatInitials(Owner owner) {
317	        if (owner == null) {
318	            return null;
319	        }
320	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
321	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
322	    }
323	
324	    Owner toOwner(OwnerDto ownerDto);
325	
326	    @Mapping(target = "id", ignore = true)
327	    @Mapping(target = "pets", ignore = true)
328	    @Mapping(target = "namesakeCount", ignore = true)
329	    @Mapping(target = "bulkSignupWarning", ignore = true)
330	    @Mapping(target = "possibleDuplicate", ignore = true)
331	    @Mapping(target = "possibleDuplicateOf", ignore = true)
332	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
333	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
334	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
335	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
336	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
337	    Owner toOwner(OwnerFieldsDto ownerDto);
338	
339	    /**
340	     * Normalize a postal address for storage into its canonical form (see
341	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
342	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
343	     * automatic method selection, so it only runs where a mapping explicitly references it via
344	     * {@code qualifiedByName}.
345	     */
346	    @Named("normalizeAddress")
347	    default String normalizeAddress(String address) {
348	        return AddressNormalizer.normalize(address);
349	    }
350	
351	    /**
352	     * Compose the single stored/returned {@code address} from whichever address fields the request
353	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
354	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
355	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
356	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
357	     * that reads the stored address consistent regardless of which form the caller used.
358	     */
359	    default String composeAddress(OwnerFieldsDto ownerDto) {
360	        if (ownerDto == null) {
361	            return null;
362	        }
363	        String line1 = ownerDto.getAddressLine1();
364	        if (line1 != null && !line1.trim().isEmpty()) {
365	            String composed = AddressNormalizer.normalize(line1);
366	            String line2 = ownerDto.getAddressLine2();
367	            if (line2 != null && !line2.trim().isEmpty()) {
368	                composed = composed + " " + AddressNormalizer.normalize(line2);
369	            }
370	            return composed;
371	        }
372	        return AddressNormalizer.normalize(ownerDto.getAddress());
373	    }
374	
375	    /**
376	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
377	     * The requirement that a valid E.164 number can be formed is enforced separately by
378	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
379	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
380	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
381	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
382	     */
383	    @Named("normalizeTelephone")
384	    default String normalizeTelephone(String telephone) {
385	        return E164Telephone.normalize(telephone);
386	    }
387	
388	    /**
389	     * Normalize an email address for storage by lower-casing it, so it is persisted and
390	     * returned in a canonical form regardless of the casing supplied by the caller.
391	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
392	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
393	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
394	     */
395	    @Named("normalizeEmail")
396	    default String normalizeEmail(String email) {
397	        return email == null ? null : email.toLowerCase();
398	    }
399	
400	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
401	
402	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
403	
404	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
405	        OwnerPageDto ownerPageDto = new OwnerPageDto();
406	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
407	        ownerPageDto.setPage(ownerPage.getNumber());
408	        ownerPageDto.setSize(ownerPage.getSize());
409	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
410	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
411	        return ownerPageDto;
412	    }
413	}
